"""Writes the generated report fixtures and scenarios; rerun after changing it and commit the output."""
import hashlib
import json
from pathlib import Path

HERE = Path(__file__).parent
SCANNER = {"name": "Trivy", "vendor": "Aqua Security", "version": "v0.60.0"}


def report(items, severity, at="2026-11-25T10:00:00Z"):
    return {"generated_at": at, "scanner": SCANNER, "severity": severity, "vulnerabilities": items}


def write(name, data):
    (HERE / "reports" / name).write_text(json.dumps(data, indent=1, ensure_ascii=False) + "\n")


def s18_edge_values():
    long_desc = " ".join(hashlib.sha256(str(i).encode()).hexdigest() for i in range(1000))[:65536]
    items = [
        {"id": "CVE-2026-1701", "package": "", "version": "1.0", "severity": "Low"},
        {"id": "CVE-2026-1702", "package": "noversion", "version": "", "severity": "Low"},
        {"id": "CVE-2026-1703", "package": "пакет-ü", "version": "1.0~β", "severity": "Medium",
         "description": "Unicode ✓ ünïcödé 漢字", "links": ["https://example.com/ü?a=1&b=2"]},
        {"id": "CVE-2026-1704", "package": "big", "version": "1", "severity": "High", "description": long_desc,
         "preferred_cvss": {"score_v3": 7.0}},
        {"id": "cve-2026-1705", "package": "case", "version": "1", "severity": "Low"},
        {"id": "CVE-2026-1705", "package": "case", "version": "1", "severity": "High"},
        {"id": "CVE-2026-1706", "package": "pipe|in|name", "version": "1", "severity": "Low",
         "links": ["https://a.example.com/x|y", "https://b.example.com"], "cwe_ids": ["CWE-1,CWE-2"]},
        {"id": "CVE-2026-1707", "package": "quote'\"pkg", "version": "1'1", "severity": "Low",
         "description": "=cmd|' /C calc'!A0"},
        {"id": "CVE-2026-1708", "package": "sevcase", "version": "1", "severity": "critical"},
    ]
    write("s18-edge-values.json", report(items, "High"))


def s20_shared():
    items = [{"id": f"CVE-2026-19{i:02d}", "package": f"pkg-{i % 7}", "version": "1.0", "severity": "High",
              "preferred_cvss": {"score_v3": 7.0 + (i % 3) / 10}} for i in range(60)]
    write("s20-shared.json", report(items, "High"))


def s23_reverse_order():
    # Same new records in opposite orders: concurrent batched inserts lock them in opposite orders.
    items = [{"id": f"CVE-2026-23{i:03d}", "package": f"pkg-{i % 11}", "version": "2.0", "severity": "Medium",
              "preferred_cvss": {"score_v3": 5.0 + (i % 5) / 10}} for i in range(120)]
    write("s23-forward.json", report(items, "Medium"))
    write("s23-reverse.json", report(list(reversed(items)), "Medium"))


def s09_overfetch():
    # One CVE across many packages and versions in many artifacts: the lookup by cve_id alone
    # returns all of them for every scan.
    steps = [{"op": "register_scanner", "scanner": "s1"}]
    for a in range(12):
        items = [{"id": "CVE-2026-0800", "package": f"lib{p}", "version": f"{a % 4}.{p}", "severity": "High",
                  "preferred_cvss": {"score_v3": 7.5}} for p in range(5)]
        items.append({"id": f"CVE-2026-08{a + 10:02d}", "package": "own", "version": str(a), "severity": "Low"})
        steps.append({"op": "scan", "artifact": f"a{a:02d}", "scanner": "s1", "report": report(items, "High")})
    steps.append({"op": "capture", "label": "all-scanned"})
    items = [{"id": "CVE-2026-0800", "package": f"lib{p}", "version": f"0.{p}", "severity": "Critical",
              "preferred_cvss": {"score_v3": 9.0}} for p in range(5)]
    steps.append({"op": "scan", "artifact": "a00", "scanner": "s1", "report": report(items, "Critical", "2026-11-26T10:00:00Z")})
    steps.append({"op": "capture", "label": "after-rescan"})
    scenario = {"name": "s09-overfetch", "description": "One CVE in many packages and versions across twelve "
                "artifacts; a rescan of one artifact changes the shared records of the artifacts with the same versions.",
                "steps": steps}
    (HERE / "scenarios" / "s09-overfetch.yaml").write_text(
        "# Generated by testdata/gen_fixtures.py.\n" + json.dumps(scenario, indent=1) + "\n")


def s18_scenario():
    scenario = {"name": "s18-edge-values", "description": "Empty package and version, Unicode, a 64 KB description, "
                "CVE ids differing only in case, separators inside values, a CSV formula and a lower-case severity.",
                "steps": [{"op": "register_scanner", "scanner": "s1"},
                          {"op": "scan", "artifact": "a1", "scanner": "s1", "report_file": "s18-edge-values.json"},
                          {"op": "capture", "label": "stored"},
                          {"op": "scan", "artifact": "a1", "scanner": "s1", "report_file": "s18-edge-values.json"},
                          {"op": "capture", "label": "rescan", "rows_unchanged": True}]}
    (HERE / "scenarios" / "s18-edge-values.yaml").write_text(
        "# Generated by testdata/gen_fixtures.py.\n" + json.dumps(scenario, indent=1) + "\n")


if __name__ == "__main__":
    s18_edge_values()
    s20_shared()
    s23_reverse_order()
    s09_overfetch()
    s18_scenario()
